module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for the K-map variables
    // x[3] is the most significant bit, x[0] is the least significant
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // Derive the two-variable groups from the K-map:
    // f = x3'x2'x1' + x3'x1 + x3x2 + x3x1'x0
    // 
    // Term 1: x3'x2'x1'  -> x3==0 && x2==0 && x1==0
    // Term 2: x3'x1      -> x3==0 && x1==1  (covers don't-cares and minterms)
    // Term 3: x3x2       -> x3==1 && x2==1  (covers minterms and don't-cares)
    // Term 4: x3x1'x0    -> x3==1 && x1==0 && x0==1 (covers minterm and don't-cares)

    assign f = (~x3 & ~x2 & ~x1) |
               (~x3 &  x1)           |
               ( x3 &  x2)           |
               ( x3 & ~x1 &  x0);

endmodule

