module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Assign the complemented outputs for the AND and OR gates
    wire q0_n = ~q0;
    wire q1_n = ~q1;
    wire q2_n = ~q2;

    // D flip-flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // q0: D input is XOR of x and its own previous output
        q0 <= x ^ q0;

        // q1: D input is AND of x and complemented previous output of q0
        q1 <= x & q0_n;

        // q2: D input is OR of x and complemented previous output of q1
        q2 <= x | q1_n;
    end

    // Three-input NOR gate whose inputs are the flip-flop outputs
    assign z = ~(q0 | q1 | q2);

endmodule

