module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    // State encoding: 2 bits for 4 states (A, B, C, D)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            A: next_state = in ? B : A;
            B: next_state = B; // in has no effect on B's next state
            C: next_state = in ? D : A;
            D: next_state = in ? B : C;
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            D: out <= 1'b1;
            default: out <= 1'b0;
        endcase
    end

    // State register (sequential logic with synchronous active-high reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= A;
        end else begin
            state <= next_state;
        end
    end

endmodule

