    reg [15:0] q_reg;

    // Assign output ports
    assign q     = q_reg;
    assign ena   = q_reg[15:13]; // Upper 3 bits are the enables

    // Synchronous always block for the counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // BCD increment logic
