    assign S110_state    = state[3];
    assign B0_state      = state[4];
    assign B1_state      = state[5];
    assign B2_state      = state[6];
    assign B3_state      = state[7];
    assign Count_state   = state[8];
    assign Wait_state    = state[9];

    // ============================================
    // Next-state assertion logic (one-hot outputs)
    // ============================================

    // B3_next: next state is B3
    assign B3_next = (S110_state & d) | (B2_state & d);

    // S_next: next state is S
    assign S_next = (~d & S_state) | (~d & S1_state) | (~d & S110_state);

    // S1_next: next state is S1
    assign S1_next = (d & S_state) | (d & S1_state);

