    assign Wait_next = (Count_state & done_counting);

    // ============================================
    // Output logic (Moore machine: outputs depend only on current state)
    // ============================================

    // shift_ena: asserted in B0, B1, B2, B3
    assign shift_ena = B0_state | B1_state | B2_state | B3_state;

    // counting: asserted in Count state
    assign counting = Count_state;

    // done: asserted in Wait state
    assign done = Wait_state;

endmodule

