    // fr0 is always asserted when there is any water (state != 11)
    // fr1 is asserted when state is 01 or 10 (between s[1] and s[0] or above s[1])
    // fr2 is asserted when state is 00 (below s[0])
    // dfr (Supplemental flow valve) is asserted when the current level is higher than the previous level change
    // We infer the "previous level" by tracking state transitions.

    // Output assignments
    assign fr0 = (state != 2'b11); // Above s[2] has no nominal flow, others have fr0
    assign fr1 = (state == 2'b01) | (state == 2'b10);
    assign fr2 = (state == 2'b00);
    assign dfr = 1'b0; // Placeholder: dfr logic depends on transition detection, implemented in always block below

