module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // State A: 3'b000
    // State B: 3'b001
    // State C: 3'b010
    // State D: 3'b011
    // State E: 3'b100
    // State F: 3'b101
    // State G: 3'b110
    // State H: 3'b111

    reg [2:0] state, next_state;

    // Output logic (Moore machine: outputs depend only on state)
    assign f = (state == 3'b001);  // f = 1 in state B
    assign g = (state == 3'b111);  // g = 1 in state H

    // State register (positive edge triggered, synchronous active low reset)
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 3'b000;  // State A
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic (combinational)
    always @(*) begin
        case (state)
            3'b000: begin // State A: reset asserted or initial
                // As long as reset is asserted, stay in A.
                // When reset is de-asserted, after next clock edge go to B.
                // Since this block is entered after posedge clk (when resetn=1),
                // we transition to B.
                next_state = 3'b001; // State B
            end
            3'b001: begin // State B: f = 1 for one cycle
                // After this cycle, monitor x.
                next_state = 3'b010; // State C
            end
            3'b010: begin // State C: monitor x for pattern 1,0,1
                // Check if we have seen 1,0,1 in the last three cycles.
                // We need to remember the previous two x values.
                // Since we only have state bits, we encode the pattern detection
                // by transitioning through states D, E, F based on x.
                if (x == 1'b1) begin
                    // First 1 of the pattern detected.
                    // Move to state D (waiting for 0).
                    next_state = 3'b011; // State D
                end else begin
                    // x is 0, not the start of pattern.
                    // Stay in C? Specification: "monitor the x input.
                    // When x has produced the values 1, 0, 1 in three successive clock cycles"
                    // If x is 0 now, we are waiting for a 1 to start the pattern.
                    // We remain in C until x=1.
                    next_state = 3'b010; // State C
                end
            end
            3'b011: begin // State D: just saw x=1, waiting for x=0
                if (x == 1'b0) begin
                    // Second bit of pattern (0) received.
                    // Move to state E (waiting for x=1).
                    next_state = 3'b100; // State E
                end else begin
                    // x is still 1. Pattern broken? 
                    // Specification says "1, 0, 1 in three successive clock cycles".
                    // If we see 1 again, we might restart or stay.
                    // Typically, we stay in D or go back to C.
                    // Let's stay in D waiting for a 0.
                    next_state = 3'b011; // State D
                end
            end
            3'b100: begin // State E: just saw x=0, waiting for x=1 (third bit)
                if (x == 1'b1) begin
                    // Third bit of pattern (1) received.
                    // Pattern 1,0,1 detected.
                    // Now we need to monitor y.
                    // Move to state F (monitor y with counter).
                    next_state = 3'b101; // State F
                end else begin
                    // x is 0, pattern not complete.
                    // Go back to C to monitor for new pattern.
                    next_state = 3'b010; // State C
                end
            end
            3'b101: begin // State F: pattern 1,0,1 detected, g should go 1 on next cycle.
                // According to spec: "When x has produced the values 1, 0, 1 in three successive clock cycles,
                // then g should be set to 1 on the following clock cycle."
                // So in this cycle (where pattern was detected in previous cycle's x),
                // we set g=1 next cycle. Here we transition to state G.
                next_state = 3'b110; // State G
            end
            3'b110: begin // State G: g = 1, monitor y. "Within at most two clock cycles, y=1"
                // We need to count cycles without y=1.
                // Let's use state H for "y not seen yet" and maybe another state?
                // Specification: "While maintaining g = 1 the FSM has to monitor the y input.
                // If y has the value 1 within at most two clock cycles, then the FSM should
                // maintain g = 1 permanently. But if y does not become 1 within two clock cycles,
                // then the FSM should set g = 0 permanently."
                // We need to track how many cycles since pattern detection.
                // Let's use state G: first cycle after g asserted.
                // State H: second cycle after g asserted.
                // If y=1 in G or H, go to state I (g permanent 1).
                // If not, go to state J (g permanent 0).
                // But we also need to handle if y=1 happens later? 
                // "Within at most two clock cycles" implies if it doesn't happen in the next two, g=0.
                // And "maintain g=1 permanently" means once y=1 seen, g stays 1.

                // Let's define:
                // State G: Cycle 1 of the 2-cycle window.
                // State H: Cycle 2 of the 2-cycle window.

                if (y == 1'b1) begin
                    // y=1 seen within the window.
                    // Maintain g=1 permanently.
                    next_state = 3'b111; // State I: g=1 permanent
                end else begin
                    // y=1 not seen yet.
                    // Check if this is the second cycle.
                    // We are in State G. If we go to H, and in H y is not 1, then g=0.
                    // So from G, we always go to H.
                    next_state = 3'b111; // State H? Wait, H is 3'b111 used for g=1 permanent.
                    // Let's re-assign states to avoid conflict.
                    // Let's use:
                    // State G: 3'b110 (g=1, cycle 1)
                    // State H: 3'b111 (g=1, cycle 2) -- but this conflicts with g=1 permanent.
